:
# Calculate the actual emissions score from the data
awk -F, '
BEGIN { print "=== Q3 2024 Emissions Data Analysis ===" }
NR>1 { 
  sum += $3; 
  count++;
  printf "Record %d: Sensor=%s, Emissions=%d\n", count, $2, $3
} 
END { 
  if (count > 0) {
    score = sum / count;
    printf "\nTotal Records: %d\n", count;
    printf "Total Emissions: %.0f\n", sum;
    printf "CALCULATED EMISSIONS SCORE: %.0f\n", score;
    printf "REGULATORY LIMIT: 100\n";
    if (score > 100) {
      printf "\n⚠️  COMPLIANCE STATUS: EXCEEDS LIMIT (Score: %.0f)\n", score;
      printf "Required Action: Immediate emissions reduction measures\n";
    } else {
      printf "\n✓ COMPLIANCE STATUS: WITHIN LIMIT\n";
    }
  }
}' /app/data/emissions_q3_2024.csv
